#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# A wizard reads answers from the keyboard, so it needs a real terminal. Run
# through a non-interactive shell (an agent's `!` prefix, a pipe, CI) the
# prompts would hit end-of-file and the first `ask` would exit silently.
if [[ ! -t 0 ]]; then
  echo "This wizard needs an interactive terminal: open one and run" >&2
  echo "  bash $0" >&2
  exit 2
fi

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=10

HOST="mini"                                  # ~/.ssh/config: kyu@192.168.219.200 (home network)
REPO_URL="https://github.com/Kyu-seok/two-birds-one-rope.git"
REMOTE_DIR='$HOME/two-birds-one-rope'        # expanded on the mini PC
SITE="https://twobirds.kyuships.com"

# remote "command" runs a shell command on the mini PC.
remote() { ssh "$HOST" "bash -lc '$1'"; }
# remote_tty "command" is the same with a terminal, for anything that asks for a sudo password.
remote_tty() { ssh -t "$HOST" "bash -lc '$1'"; }
ok()   { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
fail() { warn "$1"; SKIPPED+=("$1"); }

banner "Deploy Two Birds, One Rope to the mini PC (#9)"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Reach the mini PC"
say "Everything runs from this Mac over SSH to '$HOST' (192.168.219.200), so you need to be on the home network."
ask HOST "SSH host for the mini PC [Enter for '$HOST']:" || true
HOST="${HOST:-mini}"
if ssh -o ConnectTimeout=5 "$HOST" true; then ok "ssh $HOST works"
else warn "can't reach $HOST. Check you're at home and 'ssh $HOST' works, then re-run."; exit 1; fi
pause

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Docker on the mini PC"
if remote "docker compose version"; then ok "docker compose is installed"
else warn "docker compose isn't available on $HOST: install the Compose plugin, then re-run."; exit 1; fi
if [[ "$(remote 'systemctl is-enabled docker' 2>/dev/null)" == "enabled" ]]; then
  ok "Docker starts at boot, so the game comes back after a reboot"
else
  warn "Docker isn't enabled at boot, so the game wouldn't survive a reboot."
  if confirm "Enable it now with sudo (asks for your mini PC password)?"; then
    remote_tty "sudo systemctl enable docker" && ok "Docker enabled at boot" || fail "enable Docker at boot: sudo systemctl enable docker"
  else fail "enable Docker at boot: sudo systemctl enable docker"; fi
fi
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Get the code"
say "The repo goes in ~/two-birds-one-rope on the mini PC: cloned the first time, pulled after that."
if remote "test -d $REMOTE_DIR/.git"; then
  remote "cd $REMOTE_DIR && git pull --ff-only" && ok "pulled the latest main" || { warn "git pull failed, so fix it on the mini PC and re-run."; exit 1; }
else
  remote "git clone $REPO_URL $REMOTE_DIR" && ok "cloned into ~/two-birds-one-rope" || { warn "git clone failed."; exit 1; }
fi
remote "cd $REMOTE_DIR && git log --oneline -1"
pause

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Start the game"
say "This builds the image and starts it on 127.0.0.1:8100, where the tunnel already points."
note "It restarts unless stopped, keeps scores on the 'scores' volume, and gets twice the default CPU shares."
if confirm "Build and start it now (a few minutes the first time)?"; then
  remote "cd $REMOTE_DIR && docker compose up -d --build" && ok "the game is running" || { warn "docker compose failed: see the output above."; exit 1; }
  remote "cd $REMOTE_DIR && docker compose ps"
else
  warn "Nothing started. Re-run when you're ready."; exit 0
fi
pause

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Check it on the mini PC"
sleep 3
if remote "curl -sf -o /dev/null http://127.0.0.1:8100/"; then ok "the page answers on 127.0.0.1:8100"
else fail "the game doesn't answer on 127.0.0.1:8100: check 'docker compose logs' on the mini PC"; fi
if remote "curl -sf -X POST http://127.0.0.1:8100/api/rooms" >/dev/null; then ok "it creates Rooms"
else fail "POST /api/rooms failed on the mini PC"; fi
say "CPU shares of every running container (0 means Docker's default, 1024). The game should show 2048:"
remote "docker ps -q | xargs -r docker inspect --format \"{{.Name}} cpu_shares={{.HostConfig.CpuShares}}\""
pause "Is the game the highest? Press Enter to continue"

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Check it through the tunnel"
if curl -sf -o /dev/null "$SITE/"; then ok "$SITE answers over HTTPS with a valid certificate"
else fail "$SITE didn't answer: check the cloudflared ingress rule and 'sudo systemctl status cloudflared'"; fi
open_url "$SITE"
step "Click 'Create a Room', then 'Enter with mic', and allow the microphone."
step "Do the Calibration (silent, then your comfortable strong voice); talk to walk your Bird."
step "Keep this tab open: your partner joins it in stage 8."
pause "Did the mic and Calibration work? Press Enter to continue"

# ── 7 ────────────────────────────────────────────────────────────────────
stage "The other sites still work"
for url in "https://code-bite.com/" "https://ask.code-bite.com/health"; do
  code=$(curl -s -o /dev/null -w '%{http_code}' "$url" || true)
  if [[ "$code" == "200" ]]; then ok "$url → 200"; else fail "$url returned $code (expected 200)"; fi
done
pause

# ── 8 ────────────────────────────────────────────────────────────────────
stage "A partner on another network"
say "This is the real test: someone outside your home network joins your Room."
step "Copy the Room link from your tab (the address bar, or the link shown when you created it)."
step "Send it to your partner. They open it on their own network (not your Wi-Fi) and allow their mic."
step "Both calibrate, press Ready, and play a Run. Try the chat and voice too."
step "Check the pings at the top right: theirs should fit where they are (Korea: under ~50 ms; Europe or the US: ~150–250 ms)."
if confirm "Did your partner join, play, and show a plausible ping?"; then ok "remote join works"
else fail "remote join: note what went wrong for issue #9"; fi
pause

# ── 9 ────────────────────────────────────────────────────────────────────
stage "Reboot test (optional)"
warn "Rebooting the mini PC briefly takes down code-bite.com, ask.code-bite.com, CI and the local LLMs."
if confirm "Reboot the mini PC now to prove the game comes back on its own?"; then
  remote_tty "sudo systemctl reboot" || true
  say "Waiting for the mini PC to come back (up to 5 minutes)…"
  sleep 20
  for _ in $(seq 1 28); do ssh -o ConnectTimeout=5 "$HOST" true 2>/dev/null && break; sleep 10; done
  say "Giving Docker and the tunnel a moment…"
  sleep 20
  if curl -sf -o /dev/null "$SITE/"; then ok "the game is back after a reboot"
  else fail "after the reboot $SITE doesn't answer yet: check 'docker compose ps' on the mini PC"; fi
else
  note "Skipped. Docker starts at boot and the stack restarts unless stopped, so it should come back."
fi
pause

# ── 10 ───────────────────────────────────────────────────────────────────
stage "Route 53 cleanup (optional)"
say "DNS for kyuships.com is on Cloudflare now, so the old Route 53 hosted zone only costs ~\$0.50 a month."
ns=$(dig +short NS kyuships.com 2>/dev/null | tr '\n' ' ')
note "kyuships.com nameservers right now: ${ns:-unknown}"
if [[ "$ns" != *cloudflare* ]]; then
  warn "The nameservers aren't Cloudflare's, so don't delete the zone. Skipping."
  fail "Route 53 cleanup: nameservers aren't Cloudflare's"
elif confirm "Delete the Route 53 hosted zone for kyuships.com? (registration stays at AWS)"; then
  open_url "https://us-east-1.console.aws.amazon.com/route53/v2/hostedzones"
  step "Open the 'kyuships.com' hosted zone."
  step "Select every record except the NS and SOA records, then 'Delete records' and confirm."
  step "Back in Hosted zones, select 'kyuships.com', then 'Delete' and type the confirmation."
  note "Leave Registered domains alone: its name servers must keep pointing at Cloudflare."
  pause "Press Enter once the zone is gone"
  ok "Route 53 hosted zone deleted"
else
  note "Skipped. It's harmless, just a small monthly charge."
fi
pause

finish
say "Next time, deploying is stages 3 and 4: run this wizard again, or on the mini PC:"
note "  cd ~/two-birds-one-rope && git pull && docker compose up -d --build"
printf '\n'
}

run_wizard "$@"; exit
